// Het KNOOPMODEL van de verkenner (puur, DOM-vrij).
//
// Herbouw van het bovenste deel van viewer-bevroren/assets/verken-view.js: welke waarden
// een knoop heeft, hoeveel verwijzingen er in elke richting lopen, en hoe één
// rij leest. De URL-kant van dat bestand (VERKEN_PARAM/verkenSearch) is hier
// bewust NIET meeverhuisd: in de nieuwe app schrijft de weergavestore de hele
// adresbalk (naarUrl), dus een tweede querystring-bouwer zou een tweede bron
// van waarheid zijn. Zie verken-history.ts.
//
// WAAROM t() EN NIET tekst(). De rest van de UI-laag gebruikt tekst() uit de
// weergavestore, want dat is de reactieve leesplek. Deze module is bewust
// framework-vrij (geen solid-import, node-testbaar zonder store), en zijn
// aanroepers maken de reactiviteit zelf: het knoopmodel in verken.tsx wordt
// gebouwd in een memo die weergave.lang expliciet leest, dus een taalwissel
// bouwt deze teksten opnieuw op.
import {
  curie, incomingRefCount, incomingRefs, literalValues, localName, nodeSummary,
  outgoingRefCount, outgoingRefs, t,
} from '../../model-grens.js';
import type { Graaf, KnoopKop, PredicaatKop, Term, Verwijzing, Waarde } from '../../model-grens.js';

export interface VerkenKnoopModel {
  node: KnoopKop;
  values: Waarde[];
  inCount: number;
  outCount: number;
  /** Een knoop die alleen als VERWIJZING in de graaf voorkomt heeft niets
   *  eigens: geen waarden, geen uitgaande verwijzingen. Dat is geen fout maar
   *  een mededeling — de weergave zegt het met zoveel woorden. */
  bare: boolean;
  incoming: () => Verwijzing[];
  outgoing: () => Verwijzing[];
}

/** Het model van één knoop. De twee richtingen komen als LAZY bouwers mee:
 *  incomingRefs/outgoingRefs bouwen per verwijzing een label, en dat is bij een
 *  druk bezochte knoop (BRP: 1.392 wasDerivedFrom's op één Offer) te duur voor
 *  een blok dat dicht staat. De TELLINGEN zijn wel meteen goedkoop beschikbaar —
 *  die bepalen de kop én of het blok vanzelf open mag. */
export function verkenKnoop(store: Graaf, termOfIri: Term | string): VerkenKnoopModel {
  const node = nodeSummary(store, termOfIri);
  const inCount = incomingRefCount(store, node.term);
  const outCount = outgoingRefCount(store, node.term);
  const values = literalValues(store, node.term);
  return {
    node,
    values,
    inCount,
    outCount,
    bare: !values.length && !outCount,
    incoming: () => incomingRefs(store, node.term),
    outgoing: () => outgoingRefs(store, node.term),
  };
}

/** De tekst van één verwijzingsrij: naam (of curie, of "(anoniem)") plus het
 *  predicaat. */
export function refRijTekst(ref: Partial<Verwijzing>): { title: string; pred: string } {
  return {
    title: ref.label || ref.curie || (ref.iri ? localName(ref.iri) : t('anon')),
    pred: predicaatTekst(ref.predicate),
  };
}

export function predicaatTekst(p?: Partial<PredicaatKop> | null): string {
  if (!p) return '';
  return p.label && p.label !== p.curie ? `${p.label} (${p.curie})` : (p.curie || '');
}

// De weergavewaarde van een literal: de tekst, met taalmarkering of datatype
// als klein achtervoegsel. xsd:string en een taalloze literal krijgen er geen —
// dat zou ruis zijn op de meest voorkomende vorm.
const XSD_STRING = 'http://www.w3.org/2001/XMLSchema#string';

export function waardeTekst(v?: Partial<Waarde> | null): string {
  if (!v) return '';
  if (v.lang) return `${v.value} @${v.lang}`;
  if (v.datatype && v.datatype !== XSD_STRING) return `${v.value} (${curie(v.datatype)})`;
  return v.value || '';
}
